import{_ as a,f as e,o as d,ap as r}from"./chunks/framework.FGbRhUsL.js";const l="/wechat.jpg",m=JSON.parse('{"title":"企业支持订阅套餐对比","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"zh_CN/support/enterprise.md","filePath":"zh_CN/support/enterprise.md","lastUpdated":1795164568000}'),i={name:"zh_CN/support/enterprise.md"};function s(o,t,h,c,n,p){return d(),e("div",null,t[0]||(t[0]=[r('<h1 id="企业支持订阅套餐对比" tabindex="-1">企业支持订阅套餐对比 <a class="header-anchor" href="#企业支持订阅套餐对比" aria-label="Permalink to “企业支持订阅套餐对比”">​</a></h1><p>本页对比三档企业支持订阅套餐：优先支持版、生产保障版与尊享专属版。每档套餐的响应通道、PHP 迁移支持与框架缺陷处理范围都列在下表中。</p><div class="info custom-block has-custom-title"><p class="custom-block-title">订阅的是服务，不是软件授权</p><p>Goravel 核心框架永久以 MIT 协议开源免费。订阅仅为人工技术支持服务，不是软件授权，也不改变框架的开源授权。订阅到期后，已有的业务代码与框架使用权限不受任何影响。</p></div><h2 id="套餐对比" tabindex="-1">套餐对比 <a class="header-anchor" href="#套餐对比" aria-label="Permalink to “套餐对比”">​</a></h2><table tabindex="0"><thead><tr><th>服务项</th><th>优先支持版</th><th>生产保障版</th><th>尊享专属版</th></tr></thead><tbody><tr><td>适用场景</td><td>预上线项目、中小流量生产团队</td><td>核心线上业务团队（主力套餐）</td><td>高可用、强合规核心系统</td></tr><tr><td>问题响应通道</td><td>优先工单队列</td><td>工作日 2 小时响应</td><td>7×24 应急通道</td></tr><tr><td>版本变更风险提前通知</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>PHP 迁移支持</td><td>迁移基础咨询（年度 2 次）</td><td>迁移风险评审（年度 1 个项目，含基础咨询权益）</td><td>全流程陪伴指导（年度 1 个项目，单项目最长 3 个月，含低档位全部权益）</td></tr><tr><td>框架缺陷加急评估与临时补丁支持</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>长期兼容分支维护</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><h2 id="套餐说明" tabindex="-1">套餐说明 <a class="header-anchor" href="#套餐说明" aria-label="Permalink to “套餐说明”">​</a></h2><div class="warning custom-block has-custom-title"><p class="custom-block-title">支持范围</p><p>保障范围是 Goravel 内核与官方扩展包，业务代码与第三方中间件不在 SLA 保障范围内。所有套餐均不含驻场服务、业务定制开发，也不含迁移代码的编写与实施执行。</p></div><ol><li>PHP 迁移支持额度按年度有效，不结转、不折现。所有迁移服务都是指导与评审性质，不包含实际代码开发、迁移实施与测试执行工作。迁移服务的量化口径： <ul><li>迁移基础咨询：1 次 = 1 组关联迁移问题的集中答疑，涵盖框架对应关系、选型建议与常见坑点指引。</li><li>迁移风险评审：1 个项目 = 输出 1 份书面《迁移风险评审报告》，包含兼容性、性能、业务等价性风险与改造建议。</li><li>全流程陪伴指导：单项目服务周期最长 3 个月，超期可另行续约。</li></ul></li><li>框架缺陷加急评估与临时补丁支持：收到框架缺陷反馈后优先核验判定，评估故障影响与修复方案，按需提供主线版本发布前可用的临时补丁。这条通道只是加急，所有用户反馈的有效框架缺陷在确认后都会并入主线开源版本正常修复发布。</li><li>长期兼容分支维护：为企业维护稳定兼容分支。主线版本出现破坏性变更时，持续合并必要的缺陷修复，保障业务不被强制升级。</li></ol><h2 id="通用免责说明" tabindex="-1">通用免责说明 <a class="header-anchor" href="#通用免责说明" aria-label="Permalink to “通用免责说明”">​</a></h2><ol><li>SLA 说明：工作日指周一至周五的法定工作日，不含节假日。尊享专属版的 7×24 应急通道只针对 Goravel 框架导致的业务阻断故障，业务代码问题不在应急 SLA 内。</li><li>本页给出的方案、建议与补丁仅作为辅助。最终的业务上线、测试与风险决策由企业方负责，我们不承诺业务零故障。</li><li>各项服务额度仅限当年使用，不结转、不折现。</li></ol><h2 id="如何订阅" tabindex="-1">如何订阅 <a class="header-anchor" href="#如何订阅" aria-label="Permalink to “如何订阅”">​</a></h2><p>订阅或了解细节，可以加入 <a href="https://discord.gg/cFc5csczzS" target="_blank" rel="noreferrer">Discord</a>，也可以扫描微信群二维码联系我们。</p><p align="left"><img src="'+l+'" width="140" height="140" alt="微信群二维码"></p>',13)]))}const b=a(i,[["render",s]]);export{m as __pageData,b as default};
